-- Adds the "slips" committee tag alongside go_green/rrc, exactly the one-line CHECK edit
-- migration 007 anticipated. Granting it gates access to the bni-rrc-slips app, the same way
-- "rrc" already gates access to the bni-rrc app (see sync-committee-tag).
--
-- The existing CHECK was declared inline (`committee text not null check (...)`), so its name
-- was auto-generated by Postgres. Rather than assume that name, find it and drop it -- which
-- also makes this script safe to re-run.

do $$
declare
  existing_constraint text;
begin
  select con.conname into existing_constraint
  from pg_constraint con
  join pg_class rel on rel.oid = con.conrelid
  join pg_namespace nsp on nsp.oid = rel.relnamespace
  where nsp.nspname = 'public'
    and rel.relname = 'member_committees'
    and con.contype = 'c'
    and pg_get_constraintdef(con.oid) ilike '%committee%'
  limit 1;

  if existing_constraint is not null then
    execute format('alter table public.member_committees drop constraint %I', existing_constraint);
  end if;
end $$;

alter table public.member_committees
  add constraint member_committees_committee_check
  check (committee in ('go_green', 'rrc', 'slips'));
